"""Synthetic Riverside Grid.

Coordinates are arbitrary and do not represent a real city. The network is for
tests and demonstrations when live geographic data is not loaded.
"""

from __future__ import annotations

from typing import Any

from app.domain.demand import rebuild_land_use_demand, refresh_transit
from app.domain.network import add_directed_edge, empty_network, make_edge

SAMPLE_SLUG = "synthetic-riverside-grid"
SAMPLE_NAME = "Synthetic Riverside Grid"
SAMPLE_ATTRIBUTION = (
    "Synthetic Riverside Grid generated by UrbanTrafficLab for demonstration and tests. "
    "This is not a real city and is not derived from OpenStreetMap."
)

_NODES = [
    ("J1", "Main & First", 0.000, 0.020),
    ("J2", "Main & Second", 0.015, 0.020),
    ("J3", "Main & Third", 0.030, 0.020),
    ("J4", "Oak & First", 0.000, 0.010),
    ("J5", "Oak & Second", 0.015, 0.010),
    ("J6", "Oak & Third", 0.030, 0.010),
]

_ROADS = [
    ("R1", "Main Street", "J1", "J2", 2, 50.0, "primary"),
    ("R2", "Main Street", "J2", "J3", 2, 50.0, "primary"),
    ("R3", "Oak Street", "J4", "J5", 1, 30.0, "residential"),
    ("R4", "Oak Street", "J5", "J6", 1, 30.0, "residential"),
    ("R5", "First Avenue", "J1", "J4", 1, 40.0, "secondary"),
    ("R6", "Second Avenue", "J2", "J5", 1, 40.0, "secondary"),
    ("R7", "Third Avenue", "J3", "J6", 1, 40.0, "secondary"),
]


def build_sample_network() -> dict[str, Any]:
    network = empty_network()
    by_id: dict[str, dict[str, Any]] = {}
    for node_id, name, lon, lat in _NODES:
        node = {
            "id": node_id,
            "name": name,
            "lon": lon,
            "lat": lat,
            "kind": "intersection",
        }
        network["nodes"].append(node)
        network["intersections"].append({"node_id": node_id, "control": "uncontrolled"})
        by_id[node_id] = node
    for road_id, name, start_id, end_id, lanes, speed, road_type in _ROADS:
        forward = make_edge(
            road_id=road_id,
            name=name,
            from_node=by_id[start_id],
            to_node=by_id[end_id],
            lanes=lanes,
            speed_kmh=speed,
            road_type=road_type,
        )
        backward = make_edge(
            road_id=road_id,
            name=name,
            from_node=by_id[end_id],
            to_node=by_id[start_id],
            lanes=lanes,
            speed_kmh=speed,
            road_type=road_type,
        )
        add_directed_edge(network, forward)
        add_directed_edge(network, backward)
    network["land_uses"].append(
        {
            "id": "LU_NORTH",
            "name": "Northern District",
            "kind": "residential",
            "housing_units": 0,
            "trip_rate_per_unit_peak": 0.1,
            "trip_rate_source": "assumption",
            "geometry": {
                "type": "Polygon",
                "coordinates": [
                    [
                        [-0.002, 0.024],
                        [0.032, 0.024],
                        [0.032, 0.034],
                        [-0.002, 0.034],
                        [-0.002, 0.024],
                    ]
                ],
            },
            "assumptions": [
                "Housing units are a scenario input, not an observed census count.",
                "The polygon is a diagrammatic district, not a surveyed parcel.",
            ],
        }
    )
    network["transit_routes"].append(
        {
            "id": "BUS1",
            "name": "Crosstown",
            "mode": "bus",
            "node_ids": ["J1", "J2", "J3"],
            "edge_ids": [],
            "headway_min": 15,
            "simplified": True,
            "valid": True,
            "notes": [
                "Stops are intersections. Passenger boarding, alighting, and dwell time are not modeled."
            ],
        }
    )
    network["demand_profiles"] = [_peak_profile("morning"), _peak_profile("evening")]
    network["meta"] = {
        "comparison_peaks": [],
        "notes": ["Sample demand is synthetic and is not calibrated to traffic counts."],
        "sample": True,
        "real_city": False,
    }
    refresh_transit(network)
    rebuild_land_use_demand(network)
    return network


def _peak_profile(peak: str) -> dict[str, Any]:
    if peak == "morning":
        pairs = [
            ("od_m1", "J1", "J3", 6),
            ("od_m2", "J4", "J3", 4),
            ("od_m3", "J4", "J6", 4),
            ("od_m4", "J1", "J6", 4),
            ("od_m5", "J6", "J1", 2),
        ]
        seed = 42
        name = "Morning peak"
    else:
        pairs = [
            ("od_e1", "J3", "J1", 6),
            ("od_e2", "J3", "J4", 4),
            ("od_e3", "J6", "J4", 4),
            ("od_e4", "J6", "J1", 4),
            ("od_e5", "J1", "J6", 2),
        ]
        seed = 43
        name = "Evening peak"
    return {
        "id": f"{peak}_peak",
        "name": name,
        "peak": peak,
        "seed": seed,
        "synthetic": True,
        "observed": False,
        "horizon_s": 3600,
        "vehicle_classes": [{"id": "car", "share": 1.0}],
        "od_pairs": [
            {
                "id": pair_id,
                "origin": origin,
                "destination": destination,
                "vehicles": vehicles,
                "vehicle_class": "car",
            }
            for pair_id, origin, destination, vehicles in pairs
        ],
        "assumptions": [
            "Demand is synthetic. It is not an observed traffic count.",
            "Departure times are spread across the one-hour horizon.",
            "The default fleet is passenger cars only.",
            "Road geometry alone does not determine this demand.",
        ],
    }
